  category = 'Pengolahan Data',
  "cpId" = 'cp_inf_7_2',
  "tpId" = 'tp_inf_7_2_1',
  "targetKelas" = '7A,7B,7C',
  "targetJenjang" = 'SMP',
  "updatedAt" = NOW()
